import sys
param=0.05
def best(q):
    s=0.0; mx=0.0; beg=tmp=0; end=len(q)
    for i,ch in enumerate(q):
        qq=ord(ch)
        if qq<36: qq=36
        if qq>127: qq=127
        s += param - 10**(-(qq-33)/10.)
        if s>mx: mx=s; beg=tmp; end=i+1
        if s<0: s=0; tmp=i+1
    if mx==0: beg=end=0
    return beg,end
def bestwin(q, w, f, first=True):
    bst=None; bb=0
    for b in range(0, len(q)-w+1):
        s=sum(f(c) for c in q[b:b+w])
        if bst is None or s>bst or (not first and s==bst): bst=s; bb=b
    return bb, bb+w
