{"command":"cd /tmp/t; cat > gcref.py <<'EOF'
import sys
def nt16(c):
    t={'A':1,'C':2,'G':4,'T':8,'R':5,'Y':10,'K':12,'M':3,'S':6,'W':9,'B':14,'D':13,'H':11,'V':7,'N':15}
    return t.get(c.upper(),15)
def gc(name, s, is_at, frac, min_l, xd):
    out=[]
    L=len(s)
    start=0; hits=0; max_hits=0; start_hits=0; max_i=-1
    sc=0.0; mx=0.0
    for i in range(L+1):
        hit=0
        if i<L:
            c=nt16(s[i])
            hit = (c in (1,8,9)) if is_at else (c in (2,4,6))
            if sc==0: start=i; start_hits=hits
            sc += (1.-frac) if hit else -frac
            if sc>mx: mx=sc; max_i=i; max_hits=hits+hit
        if sc<0 or i==L or mx-sc>xd:
            if max_i>=0 and mx>0 and max_i-start+1>=min_l:
                out.append('%s\t%d\t%d\t%d'%(name,start,max_i+1,max_hits-start_hits))
            sc=0.0; mx=0.0; max_i=-1
        hits+=hit
    return out
def main():
    fn=sys.argv[1]; is_at=int(sys.argv[2]); frac=float(sys.argv[3]); min_l=int(sys.argv[4]); xd=float(sys.argv[5])
    name=None; seq=[]
    recs=[]
    for line in open(fn):
        line=line.rstrip('\n')
        if line.startswith('>'):
            if name is not None: recs.append((name,''.join(seq)))
            name=line[1:].split()[0]; seq=[]
        else: seq.append(line)
    if name is not None: recs.append((name,''.join(seq)))
    for n,s in recs:
        for o in gc(n,s,is_at,frac,min_l,xd): print(o)
main()
EOF
