/* Minimal buffered gz stream + growable string + FASTA/Q record reader.
 * Written from scratch to mimic the observed parsing behaviour of the
 * reference tool (token splitting, '\r' handling, quality length checks). */
#ifndef KIO_H
#define KIO_H

#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <zlib.h>

#define KIO_BUFSIZE 16384

#define kroundup32(x) (--(x), (x)|=(x)>>1, (x)|=(x)>>2, (x)|=(x)>>4, (x)|=(x)>>8, (x)|=(x)>>16, ++(x))

typedef struct {
	size_t l, m;
	char *s;
} kstring_t;

typedef struct {
	unsigned char *buf;
	int begin, end, is_eof;
	gzFile f;
} kstream_t;

#define KS_SEP_SPACE 0
#define KS_SEP_TAB   1
#define KS_SEP_LINE  2
#define KS_SEP_MAX   2

static inline kstream_t *ks_init(gzFile f)
{
	kstream_t *ks = (kstream_t*)calloc(1, sizeof(kstream_t));
	ks->f = f;
	ks->buf = (unsigned char*)malloc(KIO_BUFSIZE);
	return ks;
}

static inline void ks_destroy(kstream_t *ks)
{
	if (ks) { free(ks->buf); free(ks); }
}

#define ks_eof(ks) ((ks)->is_eof && (ks)->begin >= (ks)->end)

static inline int ks_getc(kstream_t *ks)
{
	if (ks->is_eof && ks->begin >= ks->end) return -1;
	if (ks->begin >= ks->end) {
		ks->begin = 0;
		ks->end = gzread(ks->f, ks->buf, KIO_BUFSIZE);
		if (ks->end == 0) { ks->is_eof = 1; return -1; }
		if (ks->end < 0) { ks->is_eof = 1; return -3; }
	}
	return (int)ks->buf[ks->begin++];
}

static inline int ks_getuntil2(kstream_t *ks, int delimiter, kstring_t *str, int *dret, int append)
{
	int gotany = 0;
	if (dret) *dret = 0;
	str->l = append? str->l : 0;
	for (;;) {
		int i;
		if (ks->begin >= ks->end) {
			if (!ks->is_eof) {
				ks->begin = 0;
				ks->end = gzread(ks->f, ks->buf, KIO_BUFSIZE);
				if (ks->end == 0) { ks->is_eof = 1; break; }
				if (ks->end < 0) { ks->is_eof = 1; return -3; }
			} else break;
		}
		if (delimiter == KS_SEP_LINE) {
			unsigned char *sep = (unsigned char*)memchr(ks->buf + ks->begin, '\n', ks->end - ks->begin);
			i = sep != NULL ? (int)(sep - ks->buf) : ks->end;
		} else if (delimiter > KS_SEP_MAX) {
			for (i = ks->begin; i < ks->end; ++i)
				if (ks->buf[i] == delimiter) break;
		} else if (delimiter == KS_SEP_SPACE) {
			for (i = ks->begin; i < ks->end; ++i)
				if (isspace(ks->buf[i])) break;
		} else if (delimiter == KS_SEP_TAB) {
			for (i = ks->begin; i < ks->end; ++i)
				if (isspace(ks->buf[i]) && ks->buf[i] != ' ') break;
		} else i = 0;
		if (str->m - str->l < (size_t)(i - ks->begin + 1)) {
			str->m = str->l + (i - ks->begin) + 1;
			kroundup32(str->m);
			str->s = (char*)realloc(str->s, str->m);
		}
		gotany = 1;
		memcpy(str->s + str->l, ks->buf + ks->begin, i - ks->begin);
		str->l = str->l + (i - ks->begin);
		ks->begin = i + 1;
		if (i < ks->end) {
			if (dret) *dret = ks->buf[i];
			break;
		}
	}
	if (!gotany && ks_eof(ks)) return -1;
	if (str->s == 0) {
		str->m = 1;
		str->s = (char*)calloc(1, 1);
	} else if (delimiter == KS_SEP_LINE && str->l > 1 && str->s[str->l-1] == '\r') --str->l;
	str->s[str->l] = '\0';
	return (int)str->l;
}

static inline int ks_getuntil(kstream_t *ks, int delimiter, kstring_t *str, int *dret)
{
	return ks_getuntil2(ks, delimiter, str, dret, 0);
}

/* ---------------- FASTA/Q record ---------------- */

typedef struct {
	kstring_t name, comment, seq, qual;
	int last_char, is_fastq;
	kstream_t *f;
} kseq_t;

static inline kseq_t *kseq_init(gzFile fd)
{
	kseq_t *s = (kseq_t*)calloc(1, sizeof(kseq_t));
	s->f = ks_init(fd);
	return s;
}

static inline void kseq_destroy(kseq_t *ks)
{
	if (!ks) return;
	free(ks->name.s); free(ks->comment.s); free(ks->seq.s); free(ks->qual.s);
	ks_destroy(ks->f);
	free(ks);
}

/* Return value: >=0 length of the sequence (normal)
   -1 end-of-file; -2 truncated quality string; -3 error reading stream */
static inline int kseq_read(kseq_t *seq)
{
	int c, r;
	kstream_t *ks = seq->f;
	if (seq->last_char == 0) {
		while ((c = ks_getc(ks)) >= 0 && c != '>' && c != '@');
		if (c < 0) return c;
		seq->last_char = c;
	}
	seq->comment.l = seq->seq.l = seq->qual.l = 0;
	if ((r = ks_getuntil(ks, 0, &seq->name, &c)) < 0) return r;
	if (c != '\n') ks_getuntil(ks, KS_SEP_LINE, &seq->comment, 0);
	if (seq->seq.s == 0) {
		seq->seq.m = 256;
		seq->seq.s = (char*)malloc(seq->seq.m);
	}
	while ((c = ks_getc(ks)) >= 0 && c != '>' && c != '+' && c != '@') {
		if (c == '\n') continue;
		seq->seq.s[seq->seq.l++] = c;
		ks_getuntil2(ks, KS_SEP_LINE, &seq->seq, 0, 1);
	}
	if (c == '>' || c == '@') seq->last_char = c;
	if (seq->seq.l + 1 >= seq->seq.m) {
		seq->seq.m = seq->seq.l + 2;
		kroundup32(seq->seq.m);
		seq->seq.s = (char*)realloc(seq->seq.s, seq->seq.m);
	}
	seq->seq.s[seq->seq.l] = 0;
	seq->is_fastq = (c == '+');
	if (!seq->is_fastq) return (int)seq->seq.l;
	if (seq->qual.m < seq->seq.m) {
		seq->qual.m = seq->seq.m;
		seq->qual.s = (char*)realloc(seq->qual.s, seq->qual.m);
	}
	while ((c = ks_getc(ks)) >= 0 && c != '\n');
	if (c == -1) return -2;
	while ((c = ks_getuntil2(ks, KS_SEP_LINE, &seq->qual, 0, 1)) >= 0 && seq->qual.l < seq->seq.l);
	if (c == -3) return -3;
	seq->last_char = 0;
	if (seq->seq.l != seq->qual.l) return -2;
	return (int)seq->seq.l;
}

/* copy helpers: an empty source field leaves the destination untouched */
static inline void cpy_kstr(kstring_t *dst, const kstring_t *src)
{
	if (src->l == 0) return;
	if (src->l + 1 > dst->m) {
		dst->m = src->l + 1;
		kroundup32(dst->m);
		dst->s = (char*)realloc(dst->s, dst->m);
	}
	dst->l = src->l;
	memcpy(dst->s, src->s, src->l + 1);
}

static inline void cpy_kseq(kseq_t *dst, const kseq_t *src)
{
	cpy_kstr(&dst->name, &src->name);
	cpy_kstr(&dst->seq, &src->seq);
	cpy_kstr(&dst->qual, &src->qual);
	cpy_kstr(&dst->comment, &src->comment);
}

#endif
