/* ---------------------------------------------------------------------- */
/* 64-bit Mersenne Twister                                                 */
/* ---------------------------------------------------------------------- */

#define MT_NN 312
#define MT_MM 156
#define MT_MATRIX_A 0xB5026F5AA96619E9ULL
#define MT_UM 0xFFFFFFFF80000000ULL
#define MT_LM 0x7FFFFFFFULL

typedef struct {
	int mti;
	uint64_t mt[MT_NN];
} mtrand_t;

static void mt_seed(mtrand_t *r, uint64_t seed)
{
	r->mt[0] = seed;
	for (r->mti = 1; r->mti < MT_NN; ++r->mti)
		r->mt[r->mti] = 6364136223846793005ULL * (r->mt[r->mti-1] ^ (r->mt[r->mti-1] >> 62)) + r->mti;
}

static mtrand_t *mt_new(uint64_t seed)
{
	mtrand_t *r = (mtrand_t*)malloc(sizeof(mtrand_t));
	mt_seed(r, seed);
	return r;
}

static uint64_t mt_next(mtrand_t *r)
{
	uint64_t x;
	static const uint64_t mag01[2] = { 0, MT_MATRIX_A };
	if (r->mti >= MT_NN) {
		int i;
		for (i = 0; i < MT_NN - MT_MM; ++i) {
			x = (r->mt[i] & MT_UM) | (r->mt[i+1] & MT_LM);
			r->mt[i] = r->mt[i+MT_MM] ^ (x>>1) ^ mag01[(int)(x&1)];
		}
		for (; i < MT_NN - 1; ++i) {
			x = (r->mt[i] & MT_UM) | (r->mt[i+1] & MT_LM);
			r->mt[i] = r->mt[i+(MT_MM-MT_NN)] ^ (x>>1) ^ mag01[(int)(x&1)];
		}
		x = (r->mt[MT_NN-1] & MT_UM) | (r->mt[0] & MT_LM);
		r->mt[MT_NN-1] = r->mt[MT_MM-1] ^ (x>>1) ^ mag01[(int)(x&1)];
		r->mti = 0;
	}
	x = r->mt[r->mti++];
	x ^= (x >> 29) & 0x5555555555555555ULL;
	x ^= (x << 17) & 0x71D67FFFEDA60000ULL;
	x ^= (x << 37) & 0xFFF7EEE000000000ULL;
	x ^= (x >> 43);
	return x;
}

#define mt_drand(r) ((mt_next(r) >> 11) * (1.0/9007199254740992.0))

/* ---------------------------------------------------------------------- */
/* Region list hash (name -> list of intervals)                            */
/* ---------------------------------------------------------------------- */

typedef struct {
	int64_t beg, end;
	char strand;
} region_t;

typedef struct {
	int n, m;
	region_t *a;
} reglist_t;

typedef struct {
	char *key;
	reglist_t val;
	int used;
} reg_slot_t;

typedef struct {
	reg_slot_t *slots;
	size_t n_slots, n_used;
} reghash_t;

static uint64_t str_hash(const char *s)
{
	uint64_t h = 1469598103934665603ULL;
	while (*s) { h ^= (unsigned char)*s++; h *= 1099511628211ULL; }
	return h;
}

static reghash_t *reg_init(void)
{
	reghash_t *h = (reghash_t*)calloc(1, sizeof(reghash_t));
	h->n_slots = 64;
	h->slots = (reg_slot_t*)calloc(h->n_slots, sizeof(reg_slot_t));
	return h;
}

static reg_slot_t *reg_find_slot(reghash_t *h, const char *key)
{
	size_t i = str_hash(key) & (h->n_slots - 1);
	while (h->slots[i].used && strcmp(h->slots[i].key, key) != 0) i = (i + 1) & (h->n_slots - 1);
	return &h->slots[i];
}

static reglist_t *reg_get(reghash_t *h, const char *key)
{
	reg_slot_t *s = reg_find_slot(h, key);
	return s->used? &s->val : 0;
}

static reglist_t *reg_put(reghash_t *h, const char *key)
{
	reg_slot_t *s;
	if ((h->n_used + 1) * 2 > h->n_slots) {
		size_t i, old_n = h->n_slots;
		reg_slot_t *old = h->slots;
		h->n_slots <<= 1;
		h->slots = (reg_slot_t*)calloc(h->n_slots, sizeof(reg_slot_t));
		for (i = 0; i < old_n; ++i)
			if (old[i].used) {
				reg_slot_t *t = reg_find_slot(h, old[i].key);
				*t = old[i];
			}
		free(old);
	}
	s = reg_find_slot(h, key);
	if (!s->used) {
		s->used = 1;
		s->key = strdup(key);
		memset(&s->val, 0, sizeof(reglist_t));
		++h->n_used;
	}
	return &s->val;
}

static void reg_destroy(reghash_t *h)
{
	size_t i;
	if (!h) return;
	for (i = 0; i < h->n_slots; ++i)
		if (h->slots[i].used) { free(h->slots[i].key); free(h->slots[i].val.a); }
	free(h->slots); free(h);
}

