		if (flag & 48) {
			if ((flag & 16) && (n_seqs & 1) == 0) continue;
			if ((flag & 32) && (n_seqs & 1) == 1) continue;
		}
		if (flag & 1024) { /* strip white spaces; length updated, NUL terminator left in place */
			size_t j;
			for (i = j = 0; i < seq->seq.l; ++i)
				if (!isspace((unsigned char)seq->seq.s[i])) seq->seq.s[j++] = seq->seq.s[i];
			seq->seq.l = j;
			if (seq->qual.l) {
				for (i = j = 0; i < seq->qual.l; ++i)
					if (!isspace((unsigned char)seq->qual.s[i])) seq->qual.s[j++] = seq->qual.s[i];
				seq->qual.l = j;
			}
		}
		if (seq->qual.l && qual_thres > qual_shift) {
			if (mask_chr) {
				for (i = 0; i < seq->seq.l; ++i)
					if (seq->qual.s[i] < qual_thres || seq->qual.s[i] > qual_thres_hi) seq->seq.s[i] = mask_chr;
			} else {
				for (i = 0; i < seq->seq.l; ++i)
					if (seq->qual.s[i] < qual_thres || seq->qual.s[i] > qual_thres_hi) seq->seq.s[i] = tolower(seq->seq.s[i]);
			}
		}
		if (flag & 256)
			for (i = 0; i < seq->seq.l; ++i) seq->seq.s[i] = toupper(seq->seq.s[i]);
		if ((flag & 512) && mask_chr)
			for (i = 0; i < seq->seq.l; ++i)
				if (islower((unsigned char)seq->seq.s[i])) seq->seq.s[i] = mask_chr;
		if (h) mask_regions(seq, h, flag & 8, mask_chr);
		if (flag & 128) {
			for (i = 0; i < seq->seq.l; ++i)
				if (nt16to4_table[nt16_table[(unsigned char)seq->seq.s[i]]] > 3) break;
			if (i < seq->seq.l) continue;
		}
		if (fake_qual) {
			if (seq->qual.m < seq->seq.m) {
				seq->qual.m = seq->seq.m;
				seq->qual.s = (char*)realloc(seq->qual.s, seq->qual.m);
			}
			seq->qual.l = seq->seq.l;
			memset(seq->qual.s, fake_qual, seq->qual.l);
			seq->qual.s[seq->qual.l] = 0;
		}
		if (flag & 1) seq->qual.l = 0;
		if (flag & 2) seq->comment.l = 0;
		if ((flag & 64) && seq->qual.l)
			for (i = 0; i < seq->qual.l; ++i) seq->qual.s[i] += 33 - qual_shift;
		if (flag & 2048) {
			print_seq_named(stdout, seq, line_len, seq->name.s, '+');
			revcomp_kseq(seq);
			print_seq_named(stdout, seq, line_len, seq->name.s, '-');
		} else {
			if (flag & 4) revcomp_kseq(seq);
			print_seq(stdout, seq, line_len);
		}
	}
	kseq_destroy(seq);
	gzclose(fp);
	reg_destroy(h);
	free(kr);
	return 0;
}

/* ---------------------------------------------------------------------- */
/* size                                                                    */
/* ---------------------------------------------------------------------- */

static int stk_size(int argc, char *argv[])
{
	gzFile fp;
	kseq_t *seq;
	uint64_t n = 0, l = 0;
	if (argc == 1 && isatty(fileno(stdin))) {
		fprintf(stderr, "Usage: seqtk size <in.fq>\n");
		return 1;
	}
	fp = argc > 1 && strcmp(argv[1], "-")? gzopen(argv[1], "r") : gzdopen(fileno(stdin), "r");
	if (fp == 0) {
		fail_open("stk_size");
		return 1;
	}
	seq = kseq_init(fp);
	while (kseq_read(seq) >= 0) ++n, l += seq->seq.l;
	kseq_destroy(seq);
	gzclose(fp);
	printf("%" PRIu64 "\t%" PRIu64 "\n", n, l);
	return 0;
}

/* ---------------------------------------------------------------------- */
/* comp                                                                    */
/* ---------------------------------------------------------------------- */

static int stk_comp(int argc, char *argv[])
{
	gzFile fp;
	kseq_t *seq;
	int l, c, upper_only = 0;
	reghash_t *h = 0;
	while ((c = getopt(argc, argv, "ur:")) >= 0) {
		switch (c) {
			case 'u': upper_only = 1; break;
			case 'r': h = reg_read(optarg); break;
		}
	}
	if (argc == optind && isatty(fileno(stdin))) {
		fprintf(stderr, "Usage:  seqtk comp [-u] [-r in.bed] <in.fa>\n\n");
		fprintf(stderr, "Output format: chr, length, #A, #C, #G, #T, #2, #3, #4, #CpG, #tv, #ts, #CpG-ts\n");
		return 1;
	}
	fp = optind < argc && strcmp(argv[optind], "-")? gzopen(argv[optind], "r") : gzdopen(fileno(stdin), "r");
	if (fp == 0) {
		fail_open("stk_comp");
		return 1;
	}
	seq = kseq_init(fp);
	while ((l = kseq_read(seq)) >= 0) {
		int k;
		reglist_t dummy, *p = 0;
		region_t dr;
		if (h) {
			p = reg_get(h, seq->name.s);
		} else {
			dr.beg = 0; dr.end = l; dr.strand = '+';
			dummy.n = dummy.m = 1; dummy.a = &dr;
			p = &dummy;
		}
		for (k = 0; p && k < p->n; ++k) {
			int64_t beg = p->a[k].beg, end = p->a[k].end, i;
			int la, lb, na, nb, cnt[11];
			if (end > (int64_t)seq->seq.m + 65536) crash_segv();
#define SEQ_AT(x) ((uint64_t)(x) < seq->seq.m? seq->seq.s[(x)] : 0)
			if (beg > 0) la = SEQ_AT(beg-1), lb = nt16_table[(unsigned char)la], lb = lb? lb : 15;
			else la = 'a', lb = -1;
			na = SEQ_AT(beg); nb = nt16_table[(unsigned char)na]; if (nb == 0) nb = 15;
			memset(cnt, 0, 11 * sizeof(int));
			for (i = beg; i < end; ++i) {
				int is_CpG = 0, a, b, cc;
				a = na; b = nb; cc = bitcnt_table[b];
				na = SEQ_AT(i+1); nb = nt16_table[(unsigned char)na]; if (nb == 0) nb = 15;
				if (b == 2 || b == 10) {
					if (nb == 4 || nb == 5) is_CpG = 1;
				} else if (b == 4 || b == 5) {
					if (lb == 2 || lb == 10) is_CpG = 1;
				}
				if (upper_only == 0 || isupper(a)) {
					if (cc > 1) {
						++cnt[cc+2];
						if (cc == 2) {
							if (b == 10 || b == 5) {
								++cnt[9];
								if (is_CpG) ++cnt[10];
							} else ++cnt[8];
						}
					} else ++cnt[nt16to4_table[b]];
					if (is_CpG) ++cnt[7];
				}
				lb = b;
			}
#undef SEQ_AT
			if (h) printf("%s\t%" PRId64 "\t%" PRId64, seq->name.s, beg, end);
			else printf("%s\t%d", seq->name.s, l);
			for (i = 0; i < 11; ++i) printf("\t%d", cnt[i]);
			putchar('\n');
		}
	}
	kseq_destroy(seq);
	gzclose(fp);
	reg_destroy(h);
	return 0;
}

/* ---------------------------------------------------------------------- */
/* sample                                                                  */
/* ---------------------------------------------------------------------- */

static int stk_sample(int argc, char *argv[])
{
	int c, twopass = 0;
	uint64_t i, num = 0, n_seqs = 0;
	double frac = 0.;
	gzFile fp;
	kseq_t *seq;
	mtrand_t *kr = 0;

	while ((c = getopt(argc, argv, "2s:")) >= 0) {
		if (c == 's') kr = mt_new(atol(optarg));
		else if (c == '2') twopass = 1;
	}
	if (kr == 0) kr = mt_new(11);
	if (optind + 2 > argc) {
		fprintf(stderr, "\nUsage:   seqtk sample [-2] [-s seed=11] <in.fa> <frac>|<number>\n\n");
		fprintf(stderr, "Options: -s INT       RNG seed [11]\n");
		fprintf(stderr, "         -2           2-pass mode: twice as slow but with much reduced memory\n\n");
		free(kr);
		return 1;
	}
	frac = atof(argv[optind+1]);
	if (frac >= 1.0) num = (uint64_t)(frac + .499), frac = 0.;
	else if (twopass) {
		fprintf(stderr, "[W::stk_sample] when sampling a fraction, option -2 is ignored.");
		twopass = 0;
	}
	if (twopass && strcmp(argv[optind], "-") == 0) {
		fprintf(stderr, "[E::stk_sample] in the 2-pass mode, the input cannot be STDIN.\n");
		free(kr);
		return 1;
	}
	fp = strcmp(argv[optind], "-")? gzopen(argv[optind], "r") : gzdopen(fileno(stdin), "r");
	if (fp == 0) {
		fail_open("stk_sample");
		free(kr);
		return 1;
	}
	seq = kseq_init(fp);
	n_seqs = 0;
	if (twopass) {
		uint64_t *buf;
		char *sel;
		uint64_t tot;
		buf = (uint64_t*)malloc(num * 8);
		while (kseq_read(seq) >= 0) {
			double r = mt_drand(kr);
			uint64_t y = n_seqs < num? n_seqs : (uint64_t)(r * (n_seqs + 1));
			if (y < num) buf[y] = n_seqs;
			++n_seqs;
		}
		kseq_destroy(seq);
		gzclose(fp);
		tot = n_seqs;
		sel = (char*)calloc(tot + 1, 1);
		for (i = 0; i < num && i < tot; ++i) sel[buf[i]] = 1;
		free(buf);
		fp = gzopen(argv[optind], "r");
		seq = kseq_init(fp);
		n_seqs = 0;
		while (kseq_read(seq) >= 0) {
			if (n_seqs < tot && sel[n_seqs]) print_seq(stdout, seq, UINT_MAX);
			++n_seqs;
		}
		free(sel);
	} else {
		kseq_t *buf = 0;
		if (num > 0) buf = (kseq_t*)calloc(num, sizeof(kseq_t));
		if (num > 0 && buf == NULL) {
			fprintf(stderr, "[E::stk_sample] Could not allocate enough memory for %" PRIu64 " sequences. Exiting...\n", num);
			free(kr);
			return 1;
		}
		while (kseq_read(seq) >= 0) {
			double r = mt_drand(kr);
			++n_seqs;
			if (num) {
				uint64_t y = n_seqs - 1 < num? n_seqs - 1 : (uint64_t)(r * n_seqs);
				if (y < num) cpy_kseq(&buf[y], seq);
			} else if (r < frac) print_seq(stdout, seq, UINT_MAX);
		}
		for (i = 0; i < num; ++i) {
			kseq_t *p = &buf[i];
			if (p->seq.l) print_seq(stdout, p, UINT_MAX);
			free(p->seq.s); free(p->qual.s); free(p->name.s); free(p->comment.s);
		}
		if (buf != NULL) free(buf);
	}
	kseq_destroy(seq);
	gzclose(fp);
	free(kr);
	return 0;
}

/* ---------------------------------------------------------------------- */
/* subseq                                                                  */
/* ---------------------------------------------------------------------- */

static int stk_subseq(int argc, char *argv[])
{
	reghash_t *h;
	gzFile fp;
	kseq_t *seq;
	int l, i, j, c, is_tab = 0, line = 0, is_strand = 0;
	while ((c = getopt(argc, argv, "tl:s")) >= 0) {
		switch (c) {
		case 't': is_tab = 1; break;
		case 's': is_strand = 1; break;
		case 'l': line = atoi(optarg); break;
		}
	}
	if (optind + 2 > argc) {
		fprintf(stderr, "Usage:   seqtk subseq [options] <in.fa> <in.bed>|<name.list>\n");
		fprintf(stderr, "Options:\n");
		fprintf(stderr, "  -t       TAB delimited output\n");
		fprintf(stderr, "  -s       strand aware\n");
		fprintf(stderr, "  -l INT   sequence line length [%d]\n", line);
		fprintf(stderr, "Note: Use 'samtools faidx' if only a few regions are intended.\n");
		return 1;
	}
	h = reg_read(argv[optind+1]);
	if (h == 0) {
		fprintf(stderr, "[E::stk_subseq] failed to read the list of regions in file '%s'\n", argv[optind+1]);
		return 1;
	}
	fp = open_in(argv[optind]);
	if (fp == 0) {
		fail_open("stk_subseq");
		return 1;
	}
	seq = kseq_init(fp);
	while ((l = kseq_read(seq)) >= 0) {
		reglist_t *p = reg_get(h, seq->name.s);
		if (p == 0) continue;
		for (i = 0; i < p->n; ++i) {
			int64_t beg = p->a[i].beg, end0 = p->a[i].end;
			uint64_t end = (uint64_t)end0;
			int whole = (beg == 0 && end0 == INT64_MAX);
			if (is_strand) {
				if (beg >= (int64_t)seq->seq.l) continue;
				if (end > seq->seq.l) end = seq->seq.l;
				if (is_tab) {
					printf("%s\t%" PRId64 "\t", seq->name.s, beg + 1);
				} else {
					if (whole) {
						if (seq->comment.l) printf("%c%s %s", seq->qual.l? '@' : '>', seq->name.s, seq->comment.s);
						else printf("%c%s", seq->qual.l? '@' : '>', seq->name.s);
					} else {
						if (seq->comment.l) printf("%c%s:%" PRId64 "-%" PRId64 " %s", seq->qual.l? '@' : '>', seq->name.s, beg+1, (int64_t)end, seq->comment.s);
						else printf("%c%s:%" PRId64 "-%" PRId64, seq->qual.l? '@' : '>', seq->name.s, beg+1, (int64_t)end);
					}
				}
				putchar('\n');
				if (p->a[i].strand == '-') {
					for (j = (int)end - 1; j >= beg; --j) putchar(comp_table[(unsigned char)seq->seq.s[j]]);
				} else {
					for (j = beg; j < (int)end; ++j) putchar(seq->seq.s[j]);
				}
				putchar('\n');
				continue;
			}
			if (beg >= (int64_t)seq->seq.l) {
				fprintf(stderr, "[subseq] %s: %" PRId64 " >= %ld\n", seq->name.s, beg, (long)seq->seq.l);
				continue;
			}
			if (end > seq->seq.l) end = seq->seq.l;
			if (is_tab) {
				printf("%s\t%" PRId64 "\t", seq->name.s, beg + 1);
				fwrite(seq->seq.s + beg, 1, end - beg, stdout);
				putchar('\n');
				continue;
			}
			if (whole) {
				if (seq->comment.l) printf("%c%s %s", seq->qual.l? '@' : '>', seq->name.s, seq->comment.s);
				else printf("%c%s", seq->qual.l? '@' : '>', seq->name.s);
			} else {
				if (seq->comment.l) printf("%c%s:%" PRId64 "-%" PRId64 " %s", seq->qual.l? '@' : '>', seq->name.s, beg+1, (int64_t)end, seq->comment.s);
				else printf("%c%s:%" PRId64 "-%" PRId64, seq->qual.l? '@' : '>', seq->name.s, beg+1, (int64_t)end);
			}
			print_str(stdout, seq->seq.s + beg, end - beg, line > 0? (unsigned)line : UINT_MAX);
			if (seq->qual.l) {
				putchar('+');
				print_str(stdout, seq->qual.s + beg, end - beg, line > 0? (unsigned)line : UINT_MAX);
			}
		}
	}
	kseq_destroy(seq);
	gzclose(fp);
	reg_destroy(h);
	return 0;
}

/* ---------------------------------------------------------------------- */
/* fqchk                                                                   */
/* ---------------------------------------------------------------------- */

typedef struct {
	int64_t q[94], b[5];
} posstat_t;

static void fqc_aux(posstat_t *p, int pos, int64_t allq[94], double perr[94], int qthres)
{
	int k;
	int64_t sum = 0, qsum = 0, sum_low = 0;
	double psum = 0;
	for (k = 0; k <= 4; ++k) sum += p->b[k];
	if (pos == 0) printf("ALL");
	else printf("%d", pos);
	printf("\t%lld", (long long)sum);
	for (k = 0; k <= 4; ++k)
		printf("\t%.1f", 100. * p->b[k] / sum);
	for (k = 0; k <= 93; ++k) {
		qsum += p->q[k] * k, psum += p->q[k] * perr[k];
		if (k < qthres) sum_low += p->q[k];
	}
	printf("\t%.1f\t%.1f", (double)qsum/sum, -4.343 * log((psum + 1e-6) / (sum + 1e-6)));
	if (qthres <= 0) {
		for (k = 0; k <= 93; ++k)
			if (allq[k] > 0) printf("\t%.2f", 100. * p->q[k] / sum);
	} else printf("\t%.1f\t%.1f", 100. * sum_low / sum, 100. * (sum - sum_low) / sum);
	putchar('\n');
}

static int stk_fqchk(int argc, char *argv[])
{
	gzFile fp;
	kseq_t *seq;
	int i, c, k, max_len = 0, max_alloc = 0, offset = 33, n_diffQ = 0, qthres = 20;
	int64_t min_len = INT64_MAX, tot_len = 0, n = 0;
	double perr[94];
	posstat_t all, *pos = 0;

	while ((c = getopt(argc, argv, "q:")) >= 0)
		if (c == 'q') qthres = atoi(optarg);

	if (argc == optind) {
		fprintf(stderr, "Usage: seqtk fqchk [-q %d] <in.fq>\n", qthres);
		fprintf(stderr, "Note: use -q0 to get the distribution of all quality values\n");
		return 1;
	}
	fp = open_in(argv[optind]);
	if (fp == 0) {
		fail_open("stk_fqchk");
		return 1;
	}
	seq = kseq_init(fp);
	for (k = 0; k <= 93; ++k)
		perr[k] = pow(10., -.1 * k);
	perr[0] = perr[1] = perr[2] = perr[3] = .5;
	while (kseq_read(seq) >= 0) {
		if (seq->qual.l == 0) continue;
		++n;
		tot_len += seq->seq.l;
		min_len = min_len < (int64_t)seq->seq.l? min_len : (int64_t)seq->seq.l;
		max_len = max_len > (int)seq->seq.l? max_len : (int)seq->seq.l;
		if (max_len > max_alloc) {
			int old_max = max_alloc;
			max_alloc = max_len;
			kroundup32(max_alloc);
			pos = (posstat_t*)realloc(pos, max_alloc * sizeof(posstat_t));
			memset(&pos[old_max], 0, (max_alloc - old_max) * sizeof(posstat_t));
		}
		for (i = 0; i < (int)seq->seq.l; ++i) {
			int q = seq->qual.s[i] - offset;
			if (q < 0) q = 0;
			if (q > 93) q = 93;
			++pos[i].q[q];
			++pos[i].b[nt6_table[(unsigned char)seq->seq.s[i]] - 1];
		}
	}
	kseq_destroy(seq);
	gzclose(fp);

	memset(&all, 0, sizeof(posstat_t));
	for (i = 0; i < max_len; ++i) {
		for (k = 0; k <= 93; ++k) all.q[k] += pos[i].q[k];
		for (k = 0; k <= 4; ++k) all.b[k] += pos[i].b[k];
	}
	for (k = n_diffQ = 0; k <= 93; ++k)
		if (all.q[k]) ++n_diffQ;
	printf("min_len: %" PRId64 "; max_len: %d; avg_len: %.2f; %d distinct quality values\n", min_len, max_len, (double)tot_len/n, n_diffQ);
	printf("POS\t#bases\t%%A\t%%C\t%%G\t%%T\t%%N\tavgQ\terrQ");
	if (qthres <= 0) {
		for (k = 0; k <= 93; ++k)
			if (all.q[k] > 0) printf("\t%%Q%d", k);
	} else printf("\t%%low\t%%high");
	putchar('\n');
	fqc_aux(&all, 0, all.q, perr, qthres);
	for (i = 0; i < max_len; ++i)
		fqc_aux(&pos[i], i + 1, all.q, perr, qthres);
	free(pos);
	return 0;
}

/* ---------------------------------------------------------------------- */
/* mergepe                                                                 */
/* ---------------------------------------------------------------------- */

static int stk_mergepe(int argc, char *argv[])
{
	gzFile fp[2];
	kseq_t *seq[2];
	if (argc < 3) {
		fprintf(stderr, "Usage: seqtk mergepe <in1.fq> <in2.fq>\n");
		return 1;
	}
	fp[0] = open_in(argv[1]);
	fp[1] = open_in(argv[2]);
	if (fp[0] == 0 || fp[1] == 0) {
		fail_open("stk_mergepe");
		return 1;
	}
	seq[0] = kseq_init(fp[0]);
	seq[1] = kseq_init(fp[1]);
	while (kseq_read(seq[0]) >= 0) {
		if (kseq_read(seq[1]) < 0) {
			fprintf(stderr, "[W::stk_mergepe] the 2nd file has fewer records.\n");
			break;
		}
		print_seq(stdout, seq[0], 0);
		print_seq(stdout, seq[1], 0);
	}
	if (kseq_read(seq[1]) >= 0)
		fprintf(stderr, "[W::stk_mergepe] the 1st file has fewer records.\n");
	kseq_destroy(seq[0]); kseq_destroy(seq[1]);
	gzclose(fp[0]); gzclose(fp[1]);
	return 0;
}

/* ---------------------------------------------------------------------- */
/* split                                                                   */
/* ---------------------------------------------------------------------- */

static int stk_split(int argc, char *argv[])
{
	gzFile fp;
	kseq_t *seq;
	int c, i, n = 10, len = 0;
	char *prefix, *fn;
	FILE **out;
	while ((c = getopt(argc, argv, "n:l:")) >= 0) {
		if (c == 'n') n = atoi(optarg);
		else if (c == 'l') len = atoi(optarg);
	}
	if (argc == optind) {
		fprintf(stderr, "Usage: seqtk split [options] <prefix> <in.fa>\n");
		fprintf(stderr, "Options:\n");
		fprintf(stderr, "  -n INT    number of files [%d]\n", n);
		fprintf(stderr, "  -l INT    line length [%d]\n", len);
		return 1;
	}
	prefix = argv[optind];
	if (argv[optind+1] == 0) crash_segv();
	fp = open_in(argv[optind+1]);
	if (fp == 0) {
		fail_open("stk_split");
		return 1;
	}
	seq = kseq_init(fp);
	out = n > 0? (FILE**)calloc(n, sizeof(FILE*)) : 0;
	fn = (char*)malloc(strlen(prefix) + 16);
	for (i = 0; i < n; ++i) {
		sprintf(fn, "%s.%.5d.fa", prefix, i + 1);
		out[i] = fopen(fn, "w+");
		if (out[i] == 0) {
			fprintf(stderr, "ERROR: failed to create file %s\n", fn);
			exit(1);
		}
	}
	free(fn);
	i = 0;
	while (kseq_read(seq) >= 0) {
		if (n == 0) { fflush(stdout); raise(SIGFPE); _exit(136); }
		if (out == 0) crash_segv();
		print_seq(out[i % n], seq, len);
		++i;
	}
	for (i = 0; i < n; ++i) fclose(out[i]);
	free(out);
	kseq_destroy(seq);
	gzclose(fp);
	return 0;
}

/* ---------------------------------------------------------------------- */
/* trimfq                                                                  */
/* ---------------------------------------------------------------------- */

static int stk_trimfq(int argc, char *argv[])
{
	gzFile fp;
	kseq_t *seq;
	double param = 0.05, q_int2real[128];
	int i, c, min_len = 30, left = 0, right = 0, max_len = 0;
	while ((c = getopt(argc, argv, "l:q:b:e:L:")) >= 0) {
		switch (c) {
			case 'q': param = atof(optarg); break;
			case 'l': min_len = atoi(optarg); break;
			case 'b': left = atoi(optarg); break;
			case 'e': right = atoi(optarg); break;
			case 'L': max_len = atoi(optarg); break;
		}
	}
	if (optind == argc) {
		fprintf(stderr, "\n");
		fprintf(stderr, "Usage:   seqtk trimfq [options] <in.fq>\n\n");
		fprintf(stderr, "Options: -q FLOAT    error rate threshold (disabled by -b/-e) [%.2f]\n", param);
		fprintf(stderr, "         -l INT      maximally trim down to INT bp (disabled by -b/-e) [%d]\n", min_len);
		fprintf(stderr, "         -b INT      trim INT bp from left (non-zero to disable -q/-l) [0]\n");
		fprintf(stderr, "         -e INT      trim INT bp from right (non-zero to disable -q/-l) [0]\n");
		fprintf(stderr, "         -L INT      retain at most INT bp from the 5'-end (non-zero to disable -q/-l) [0]\n");
		fprintf(stderr, "         -Q          force FASTQ output\n");
		fprintf(stderr, "\n");
		return 1;
	}
	fp = open_in(argv[optind]);
	if (fp == 0) {
		fail_open("stk_trimfq");
		return 1;
	}
	seq = kseq_init(fp);
	for (i = 0; i < 128; ++i)
		q_int2real[i] = pow(10., -(i - 33) / 10.);
	while (kseq_read(seq) >= 0) {
		int beg, tmp, end;
		double s, max;
		if (left || right || max_len > 0) {
			beg = left; end = (int)seq->seq.l - right;
			if (beg >= end) beg = end = 0;
			if (max_len > 0 && end - beg > max_len) end = beg + max_len;
		} else if (seq->qual.l > (size_t)min_len) {
			for (i = 0, beg = tmp = 0, end = (int)seq->qual.l, s = max = 0.; i < (int)seq->qual.l; ++i) {
				int q = (unsigned char)seq->qual.s[i];
				if (q < 36) q = 36;
				if (q > 127) q = 127;
				s += param - q_int2real[q];
				if (s > max) max = s, beg = tmp, end = i + 1;
				if (s < 0) s = 0, tmp = i + 1;
			}
			if (max == 0.) beg = end = 0;
			if (end - beg < min_len) { /* pick the min_len window with the highest total quality */
				int j, l = (int)seq->qual.l;
				long sum = 0, best;
				int best_b = 0;
				for (j = 0; j < min_len; ++j) sum += (unsigned char)seq->qual.s[j];
				best = sum;
				for (j = min_len; j < l; ++j) {
					sum += (unsigned char)seq->qual.s[j] - (unsigned char)seq->qual.s[j - min_len];
					if (sum > best) best = sum, best_b = j - min_len + 1;
				}
				beg = best_b; end = beg + min_len;
			}
		} else beg = 0, end = (int)seq->seq.l;
		putchar(seq->qual.l? '@' : '>'); fputs(seq->name.s, stdout);
		if (seq->comment.l) { putchar(' '); puts(seq->comment.s); }
		else putchar('\n');
		if (end > beg) fwrite(seq->seq.s + beg, 1, end - beg, stdout);
		putchar('\n');
		if (seq->qual.l) {
			puts("+");
			if (end > beg) fwrite(seq->qual.s + beg, 1, end - beg, stdout);
			putchar('\n');
		}
	}
	kseq_destroy(seq);
	gzclose(fp);
	return 0;
}

/* ---------------------------------------------------------------------- */
/* hety                                                                    */
/* ---------------------------------------------------------------------- */

static int stk_hety(int argc, char *argv[])
{
	gzFile fp;
	kseq_t *seq;
	int l, c, win_size = 50000, n_start = 5, win_step, is_lower_mask = 0;
	char *buf;
	uint32_t cnt[3];
	while ((c = getopt(argc, argv, "w:t:m")) >= 0) {
		switch (c) {
		case 'w': win_size = atoi(optarg); break;
		case 't': n_start = atoi(optarg); break;
		case 'm': is_lower_mask = 1; break;
		}
	}
	if (argc == 1) {
		fprintf(stderr, "\n");
		fprintf(stderr, "Usage:   seqtk hety [options] <in.fa>\n\n");
		fprintf(stderr, "Options: -w INT   window size [%d]\n", win_size);
		fprintf(stderr, "         -t INT   # start positions in a window [%d]\n", n_start);
		fprintf(stderr, "         -m       treat lowercases as masked\n");
		fprintf(stderr, "\n");
		return 1;
	}
	if (argv[optind] == 0) crash_segv();
	fp = open_in(argv[optind]);
	if (fp == 0) {
		fail_open("stk_hety");
		return 1;
	}
	seq = kseq_init(fp);
	if (n_start == 0) { fflush(stdout); raise(SIGFPE); _exit(136); }
	win_step = win_size / n_start;
	buf = (char*)calloc(win_size > 0? win_size : 1, 1);
	while ((l = kseq_read(seq)) >= 0) {
		int x, i, y, z, next = 0;
		cnt[0] = cnt[1] = cnt[2] = 0;
		for (i = 0; i <= l; ++i) {
			if ((i >= win_size && i % win_step == 0) || i == l) {
				if (i == l && l >= win_size) {
					for (y = l - win_size; y < next; ++y) --cnt[(int)buf[y % win_size]];
				}
				if (cnt[1] + cnt[2] > 0)
					printf("%s\t%d\t%d\t%.2f\t%d\t%d\n", seq->name.s, next, i,
						   (double)cnt[2] / (cnt[1] + cnt[2]) * win_size, cnt[1] + cnt[2], cnt[2]);
				next = i;
			}
			if (i < l) {
				y = i % win_size;
				c = (unsigned char)seq->seq.s[i];
				if (is_lower_mask && islower(c)) c = 'N';
				c = nt16_table[c];
				x = bitcnt_table[c];
				if (i >= win_size) --cnt[(int)buf[y]];
				buf[y] = z = (x == 1)? 1 : (x == 2)? 2 : 0;
				++cnt[z];
			}
		}
	}
	free(buf);
	kseq_destroy(seq);
	gzclose(fp);
	return 0;
}

/* ---------------------------------------------------------------------- */
/* gc                                                                      */
/* ---------------------------------------------------------------------- */

static int stk_gc(int argc, char *argv[])
{
	int c, is_at = 0, min_l = 20;
	double frac = 0.6f, xdropoff = 10.0f;
	gzFile fp;
	kseq_t *seq;

	while ((c = getopt(argc, argv, "wf:l:x:")) >= 0) {
		if (c == 'w') is_at = 1;
		else if (c == 'f') frac = atof(optarg);
		else if (c == 'l') min_l = atoi(optarg);
		else if (c == 'x') xdropoff = atof(optarg);
	}
	if (optind + 1 > argc) {
		fprintf(stderr, "Usage: seqtk gc [options] <in.fa>\n");
		fprintf(stderr, "Options:\n");
		fprintf(stderr, "  -w         identify high-AT regions\n");
		fprintf(stderr, "  -f FLOAT   min GC fraction (or AT fraction for -w) [%.2f]\n", frac);
		fprintf(stderr, "  -l INT     min region length to output [%d]\n", min_l);
		fprintf(stderr, "  -x FLOAT   X-dropoff [%.1f]\n", xdropoff);
		return 1;
	}
	fp = open_in(argv[optind]);
	if (fp == 0) {
		fail_open("stk_gc");
		return 1;
	}
	seq = kseq_init(fp);
	while (kseq_read(seq) >= 0) {
		int64_t i, L = seq->seq.l, start = 0, hits = 0, start_hits = 0, smax_i = -1, smax_hits = 0;
		double sc = 0., smax = 0., ph = (1. - frac) / frac;
		for (i = 0; i < L; ++i) {
			int cc = nt16_table[(unsigned char)seq->seq.s[i]];
			int hit = is_at? (cc == 1 || cc == 8 || cc == 9) : (cc == 2 || cc == 4 || cc == 6);
			if (sc == 0) {
				if (!hit) continue;
				start = i; start_hits = hits;
			}
			hits += hit;
			sc += hit? ph : -1.;
			if (sc > smax) smax = sc, smax_i = i, smax_hits = hits;
			if (sc < 0 || smax - sc > xdropoff) {
				if (smax_i >= start && smax_i - start + 1 >= min_l)
					printf("%s\t%" PRId64 "\t%" PRId64 "\t%" PRId64 "\n", seq->name.s, start, smax_i + 1, smax_hits - start_hits);
				i = smax_i; hits = smax_hits;
				sc = 0.; smax = 0.; smax_i = -1;
			}
		}
		if (smax_i >= start && smax_i - start + 1 >= min_l)
			printf("%s\t%" PRId64 "\t%" PRId64 "\t%" PRId64 "\n", seq->name.s, start, smax_i + 1, smax_hits - start_hits);
	}
	kseq_destroy(seq);
	gzclose(fp);
	return 0;
}

/* ---------------------------------------------------------------------- */
/* mutfa                                                                   */
/* ---------------------------------------------------------------------- */

typedef struct {
	int64_t pos;
	int base;
} mut_t;

typedef struct {
	int n, m;
	mut_t *a;
} mutlist_t;

static int stk_mutfa(int argc, char *argv[])
{
	reghash_t *h;
	gzFile fp;
	kseq_t *seq;
	kstream_t *ks;
	int l, i, dret;
	kstring_t str = {0,0,0};
	if (argc < 3) {
		fprintf(stderr, "Usage: seqtk mutfa <in.fa> <in.snp>\n\n");
		fprintf(stderr, "Note: <in.snp> contains at least four columns per line which are:\n");
		fprintf(stderr, "      'chr  1-based-pos  any  base-changed-to'.\n");
		return 1;
	}
	/* mutation list stored as regions: beg = position (0-based), end = base char */
	fp = open_in(argv[2]);
	if (fp == 0) {
		fail_open("stk_mutfa");
		return 1;
	}
	h = reg_init();
	ks = ks_init(fp);
	while (ks_getuntil(ks, 0, &str, &dret) >= 0) {
		int64_t beg = 0;
		int base = 0;
		reglist_t *p = reg_put(h, str.s);
		if (ks_getuntil(ks, 0, &str, &dret) > 0) beg = atol(str.s) - 1;
		ks_getuntil(ks, 0, &str, &dret);
		if (ks_getuntil(ks, 0, &str, &dret) > 0 && str.l == 1 && isalpha((unsigned char)str.s[0])) base = str.s[0];
		if (p->n == p->m) {
			p->m = p->m? p->m<<1 : 4;
			p->a = (region_t*)realloc(p->a, p->m * sizeof(region_t));
		}
		p->a[p->n].beg = beg; p->a[p->n].end = base; p->a[p->n].strand = 0;
		++p->n;
		if (dret != '\n') while ((dret = ks_getc(ks)) > 0 && dret != '\n');
	}
	ks_destroy(ks);
	gzclose(fp);
	free(str.s);
	fp = open_in(argv[1]);
	if (fp == 0) {
		fail_open("stk_mutfa");
		return 1;
	}
	seq = kseq_init(fp);
	while ((l = kseq_read(seq)) >= 0) {
		reglist_t *p = reg_get(h, seq->name.s);
		if (p) {
			for (i = 0; i < p->n; ++i) {
				int64_t beg = p->a[i].beg;
				if (beg >= 0 && beg < (int64_t)seq->seq.l && p->a[i].end)
					seq->seq.s[beg] = (char)p->a[i].end;
			}
		}
		printf(">%s", seq->name.s);
		for (i = 0; i < l; ++i) {
			if (i%60 == 0) putchar('\n');
			putchar(seq->seq.s[i]);
		}
		putchar('\n');
	}
	kseq_destroy(seq);
	gzclose(fp);
	reg_destroy(h);
	return 0;
}

/* ---------------------------------------------------------------------- */
/* mergefa                                                                 */
/* ---------------------------------------------------------------------- */

static int stk_mergefa(int argc, char *argv[])
{
	gzFile fp[2];
	kseq_t *seq[2];
	int i, l, c, is_intersect = 0, is_haploid = 0, qual = 0, is_mask = 0, is_randhet = 0;
	uint64_t cnt[5];
	while ((c = getopt(argc, argv, "himrq:")) >= 0) {
		switch (c) {
			case 'i': is_intersect = 1; break;
			case 'h': is_haploid = 1; break;
			case 'm': is_mask = 1; break;
			case 'r': is_randhet = 1; break;
			case 'q': qual = atoi(optarg); break;
		}
	}
	if (is_mask && is_intersect) {
		fprintf(stderr, "[stk_mergefa] `-i' and `-h' cannot be applied at the same time.\n");
		return 1;
	}
	if (optind + 2 > argc) {
		fprintf(stderr, "\nUsage: seqtk mergefa [options] <in1.fa> <in2.fa>\n\n");
		fprintf(stderr, "Options: -q INT   quality threshold [0]\n");
		fprintf(stderr, "         -i       take intersection\n");
		fprintf(stderr, "         -m       convert to lowercase when one of the input base is N\n");
		fprintf(stderr, "         -r       pick a random allele from het\n");
		fprintf(stderr, "         -h       suppress hets in the input\n\n");
		return 1;
	}
	for (i = 0; i < 2; ++i) {
		fp[i] = open_in(argv[optind+i]);
		seq[i] = fp[i]? kseq_init(fp[i]) : 0;
	}
	if (fp[0] == 0 || fp[1] == 0) {
		fail_open("stk_mergefa");
		return 1;
	}
	cnt[0] = cnt[1] = cnt[2] = cnt[3] = cnt[4] = 0;
	srand48(1);
	while (kseq_read(seq[0]) >= 0) {
		int min_l, c0, c1, b0, b1, is_upper;
		kseq_read(seq[1]);
		if (strcmp(seq[0]->name.s, seq[1]->name.s))
			fprintf(stderr, "[stk_mergefa] Different sequence names: %s != %s\n", seq[0]->name.s, seq[1]->name.s);
		if (seq[0]->seq.l != seq[1]->seq.l)
			fprintf(stderr, "[stk_mergefa] Unequal sequence length: %ld != %ld\n", (long)seq[0]->seq.l, (long)seq[1]->seq.l);
		min_l = seq[0]->seq.l < seq[1]->seq.l? (int)seq[0]->seq.l : (int)seq[1]->seq.l;
		printf(">%s", seq[0]->name.s);
		for (l = 0; l < min_l; ++l) {
			int out;
			c0 = (unsigned char)seq[0]->seq.s[l]; c1 = (unsigned char)seq[1]->seq.s[l];
			if (seq[0]->qual.l && seq[0]->qual.s[l] - 33 < qual) c0 = tolower(c0);
			if (seq[1]->qual.l && seq[1]->qual.s[l] - 33 < qual) c1 = tolower(c1);
			if (is_intersect || is_mask) is_upper = (isupper(c0) || isupper(c1))? 1 : 0;
			else is_upper = (isupper(c0) && isupper(c1))? 1 : 0;
			c0 = nt16_table[c0]; c1 = nt16_table[c1];
			if (c0 == 0) c0 = 15;
			if (c1 == 0) c1 = 15;
			b0 = bitcnt_table[c0]; b1 = bitcnt_table[c1];
			if (is_upper && b0 <= 2 && b1 <= 2) {
				if (b0 == 1 && b1 == 1) {
					if (c0 == c1) ++cnt[0];
					else ++cnt[1];
				} else if (b0 == 1) ++cnt[2];
				else if (b1 == 1) ++cnt[3];
				else ++cnt[4];
			}
			if (is_haploid && (b0 > 1 || b1 > 1)) is_upper = 0;
			if (is_intersect || is_mask) {
				int x = c0 & c1;
				if (is_mask && (c0 == 15 || c1 == 15)) {
					x = (c0 == 15)? c1 : c0;
					is_upper = 0;
				}
				if (x == 0) out = 'x';
				else out = is_upper? nt16_rev_table[x] : tolower(nt16_rev_table[x]);
			} else if (is_randhet) {
				if (b0 > 2 || b1 > 2) out = tolower(nt16_rev_table[c0]);
				else if (b0 == 1 && b1 == 1) {
					int x = c0 | c1;
					out = is_upper? nt16_rev_table[x] : tolower(nt16_rev_table[x]);
				} else if ((c0 & c1) == 0) out = tolower(nt16_rev_table[c0]);
				else if (c0 == c1) {
					int x = c0;
					if ((lrand48() & 1) == 0) {
						int lo = x & -x, hi = x ^ lo;
						x = (lrand48() & 1)? lo : hi;
					}
					out = is_upper? nt16_rev_table[x] : tolower(nt16_rev_table[x]);
				} else if (b0 == 1 || b1 == 1) {
					int het = (b0 == 1)? c1 : c0, hom = (b0 == 1)? c0 : c1;
					int x = (lrand48() & 1)? het : hom;
					out = is_upper? nt16_rev_table[x] : tolower(nt16_rev_table[x]);
				} else out = tolower(nt16_rev_table[c0]);
			} else {
				int x = c0 | c1;
				out = is_upper? nt16_rev_table[x] : tolower(nt16_rev_table[x]);
			}
			if (l % 60 == 0) putchar('\n');
			putchar(out);
		}
		putchar('\n');
	}
	fprintf(stderr, "[stk_mergefa] (same,diff,hom-het,het-hom,het-het)=(%" PRIu64 ",%" PRIu64 ",%" PRIu64 ",%" PRIu64 ",%" PRIu64 ")\n", cnt[0], cnt[1], cnt[2], cnt[3], cnt[4]);
	for (i = 0; i < 2; ++i) { kseq_destroy(seq[i]); gzclose(fp[i]); }
	return 0;
}

/* ---------------------------------------------------------------------- */
/* famask                                                                  */
/* ---------------------------------------------------------------------- */

static int stk_famask(int argc, char *argv[])
{
	gzFile fp[2];
	kseq_t *seq[2];
	int i, l, c;
	while ((c = getopt(argc, argv, "")) >= 0);
	if (argc - optind < 2) {
		fprintf(stderr, "Usage: seqtk famask <src.fa> <mask.fa>\n");
		return 1;
	}
	for (i = 0; i < 2; ++i) {
		fp[i] = open_in(argv[optind+i]);
		seq[i] = fp[i]? kseq_init(fp[i]) : 0;
	}
	if (fp[0] == 0 || fp[1] == 0) {
		fail_open("stk_famask");
		return 1;
	}
	while (kseq_read(seq[0]) >= 0) {
		int min_l;
		kseq_read(seq[1]);
		if (strcmp(seq[0]->name.s, seq[1]->name.s))
			fprintf(stderr, "[stk_famask] Different sequence names: %s != %s\n", seq[0]->name.s, seq[1]->name.s);
		if (seq[0]->seq.l != seq[1]->seq.l)
			fprintf(stderr, "[stk_famask] Unequal sequence length: %ld != %ld\n", (long)seq[0]->seq.l, (long)seq[1]->seq.l);
		min_l = seq[0]->seq.l < seq[1]->seq.l? (int)seq[0]->seq.l : (int)seq[1]->seq.l;
		printf(">%s", seq[0]->name.s);
		for (l = 0; l < min_l; ++l) {
			int c0 = (unsigned char)seq[0]->seq.s[l], c1 = (unsigned char)seq[1]->seq.s[l], out;
			if (c1 == 'X') out = c0;
			else if (c1 == 'x') out = tolower(c0);
			else out = c1;
			if (l % 60 == 0) putchar('\n');
			putchar(out);
		}
		putchar('\n');
	}
	for (i = 0; i < 2; ++i) { kseq_destroy(seq[i]); gzclose(fp[i]); }
	return 0;
}

/* ---------------------------------------------------------------------- */
/* dropse / rename                                                         */
/* ---------------------------------------------------------------------- */

static int name_is_diff(const kstring_t *p, const kstring_t *q)
{
	if (p->l != q->l) return 1;
	if (p->l > 2 && p->s[p->l-2] == '/' && q->s[q->l-2] == '/'
		&& isdigit((unsigned char)p->s[p->l-1]) && isdigit((unsigned char)q->s[q->l-1]))
		return strncmp(p->s, q->s, p->l - 2) != 0;
	return strcmp(p->s, q->s) != 0;
}

static int stk_dropse(int argc, char *argv[])
{
	gzFile fp;
	kseq_t *seq, last;
	if (argc == 1 && isatty(fileno(stdin))) {
		fprintf(stderr, "Usage: seqtk dropse <in.fq>\n");
		return 1;
	}
	fp = argc > 1 && strcmp(argv[1], "-")? gzopen(argv[1], "r") : gzdopen(fileno(stdin), "r");
	if (fp == 0) {
		fail_open("stk_dropse");
		return 1;
	}
	seq = kseq_init(fp);
	memset(&last, 0, sizeof(kseq_t));
	while (kseq_read(seq) >= 0) {
		if (last.name.l) {
			if (!name_is_diff(&last.name, &seq->name)) {
				print_seq(stdout, &last, 0);
				print_seq(stdout, seq, 0);
				last.name.l = 0;
			} else cpy_kseq(&last, seq);
		} else cpy_kseq(&last, seq);
	}
	kseq_destroy(seq);
	gzclose(fp);
	free(last.name.s); free(last.seq.s); free(last.qual.s); free(last.comment.s);
	return 0;
}

static int stk_rename(int argc, char *argv[])
{
	gzFile fp;
	kseq_t *seq, last;
	char *prefix = 0;
	uint64_t n = 0;
	if (argc == 1 && isatty(fileno(stdin))) {
		fprintf(stderr, "Usage: seqtk rename <in.fq> [prefix]\n");
		return 1;
	}
	fp = argc > 1 && strcmp(argv[1], "-")? gzopen(argv[1], "r") : gzdopen(fileno(stdin), "r");
	if (fp == 0) {
		fail_open("stk_rename");
		return 1;
	}
	if (argc > 2) prefix = argv[2];
	seq = kseq_init(fp);
	memset(&last, 0, sizeof(kseq_t));
	while (kseq_read(seq) >= 0) {
		char buf[64];
		int same = 0;
		if (last.name.l) {
			if (!name_is_diff(&last.name, &seq->name)) same = 1;
		}
		if (!same) ++n;
		cpy_kseq(&last, seq);
		sprintf(buf, "%" PRIu64, n);
		if (prefix) {
			char *nm = (char*)malloc(strlen(prefix) + strlen(buf) + 1);
			strcpy(nm, prefix); strcat(nm, buf);
			print_seq_named(stdout, &last, 0, nm, 0);
			free(nm);
		} else print_seq_named(stdout, &last, 0, buf, 0);
		if (same) last.name.l = 0;
	}
	kseq_destroy(seq);
	gzclose(fp);
	free(last.name.s); free(last.seq.s); free(last.qual.s); free(last.comment.s);
	return 0;
}

