	gzclose(fp);
	return 0;
}

/* ---------------------------------------------------------------------- */
/* telo                                                                    */
/* ---------------------------------------------------------------------- */

static int stk_telo(int argc, char *argv[])
{
	gzFile fp;
	kseq_t *ks;
	int c, mlen, i, j, penalty = 1, min_score = 300, print_scoring = 0;
	int64_t max_drop = 2000, tot_telo = 0, tot_len = 0;
	const char *motif = "CCCTAA";
	uint64_t *mt, mask;

	while ((c = getopt(argc, argv, "m:p:d:s:P")) >= 0) {
		if (c == 'm') motif = optarg;
		else if (c == 'p') penalty = atoi(optarg);
		else if (c == 'd') max_drop = atol(optarg);
		else if (c == 's') min_score = atoi(optarg);
		else if (c == 'P') print_scoring = 1;
	}
	if (argc == optind && isatty(fileno(stdin))) {
		fprintf(stderr, "Usage: seqtk telo [options] <in.fq>\n");
		fprintf(stderr, "Options:\n");
		fprintf(stderr, "  -m STR     motif [%s]\n", motif);
		fprintf(stderr, "  -p INT     penalty [%d]\n", penalty);
		fprintf(stderr, "  -d INT     max drop [%" PRId64 "]\n", max_drop);
		fprintf(stderr, "  -s INT     min score [%d]\n", min_score);
		fprintf(stderr, "  -P         print scoring\n");
		return 1;
	}
	if (argc > 1 && argv[optind] == 0) crash_segv();
	fp = argc > 1 && strcmp(argv[optind], "-")? gzopen(argv[optind], "r") : gzdopen(fileno(stdin), "r");
	if (fp == 0) {
		fail_open("stk_telo");
		return 1;
	}
	mlen = strlen(motif);
	mask = mlen >= 32? ~0ULL : (1ULL << (2*mlen)) - 1;
	mt = (uint64_t*)calloc(mlen > 0? mlen : 1, 8);
	for (i = 0; i < mlen; ++i) {
		uint64_t x = 0;
		for (j = 0; j < mlen; ++j) {
			int cc = nt6_table[(unsigned char)motif[(i + j) % mlen]];
			if (!(cc >= 1 && cc <= 4)) {
				fflush(stdout);
				fprintf(stderr, "%s: seqtk.c:2005: stk_telo: Assertion `c >= 1 && c <= 4' failed.\n", program_invocation_short_name);
				abort();
			}
			x = (x << 2 | (cc - 1)) & mask;
		}
		mt[i] = x;
	}
	ks = kseq_init(fp);
	while (kseq_read(ks) >= 0) {
		int64_t l = ks->seq.l, st, en_p = 0;
		tot_len += l;
		for (st = 0; st < 2; ++st) {
			int64_t score = 0, max = 0, max_i = -1, n_valid = 0, lim;
			uint64_t x = 0;
			lim = st == 0? l : l - en_p;
			for (i = 0; i < lim; ++i) {
				int cc, hit = 0;
				if (st == 0) {
					if (print_scoring) printf("P\t%s\t%d\t%" PRId64 "\t%" PRId64 "\n", ks->name.s, i, score, max);
					cc = nt6_table[(unsigned char)ks->seq.s[i]];
				} else {
					cc = nt6_table[(unsigned char)ks->seq.s[l - 1 - i]];
					if (cc >= 1 && cc <= 4) cc = 5 - cc;
				}
				if (cc >= 1 && cc <= 4) {
					x = (x << 2 | (cc - 1)) & mask;
					++n_valid;
				} else n_valid = 0, x = 0;
				if (i >= mlen) {
					if (n_valid >= mlen)
						for (j = 0; j < mlen; ++j)
							if (mt[j] == x) { hit = 1; break; }
					if (hit) ++score;
					else score -= penalty;
					if (score > max) max = score, max_i = i;
					else if (max - score > max_drop) break;
				}
				if (st == 1 && print_scoring) printf("Q\t%s\t%d\t%" PRId64 "\t%" PRId64 "\n", ks->name.s, i + 1, score, max);
			}
			if (max >= min_score) {
				if (st == 0) {
					en_p = max_i + 1;
					if (!print_scoring) printf("%s\t%d\t%" PRId64 "\t%" PRId64 "\n", ks->name.s, 0, en_p, l);
					tot_telo += en_p;
				} else {
					int64_t s0 = l - max_i - 1;
					if (!print_scoring) printf("%s\t%" PRId64 "\t%" PRId64 "\t%" PRId64 "\n", ks->name.s, s0, l, l);
					tot_telo += l - s0;
				}
			}
		}
	}
	fprintf(stderr, "%" PRId64 "\t%" PRId64 "\n", tot_telo, tot_len);
	free(mt);
	kseq_destroy(ks);
	gzclose(fp);
	return 0;
}

