	while ((c = getopt(argc, argv, "")) >= 0);
	if (argc - optind < 2) {
		fprintf(stderr, "Usage: seqtk famask <src.fa> <mask.fa>\n");
		return 1;
	}
	for (i = 0; i < 2; ++i) {
		fp[i] = open_in(argv[optind+i]);
		seq[i] = fp[i]? kseq_init(fp[i]) : 0;
	}
	if (fp[0] == 0 || fp[1] == 0) {
		fail_open("stk_famask");
		return 1;
	}
	while (kseq_read(seq[0]) >= 0) {
		int min_l;
		kseq_read(seq[1]);
		if (strcmp(seq[0]->name.s, seq[1]->name.s))
			fprintf(stderr, "[stk_famask] Different sequence names: %s != %s\n", seq[0]->name.s, seq[1]->name.s);
		if (seq[0]->seq.l != seq[1]->seq.l)
			fprintf(stderr, "[stk_famask] Unequal sequence length: %ld != %ld\n", (long)seq[0]->seq.l, (long)seq[1]->seq.l);
		min_l = seq[0]->seq.l < seq[1]->seq.l? (int)seq[0]->seq.l : (int)seq[1]->seq.l;
		printf(">%s", seq[0]->name.s);
		for (l = 0; l < min_l; ++l) {
			int c0 = (unsigned char)seq[0]->seq.s[l], c1 = (unsigned char)seq[1]->seq.s[l], out;
			if (c1 == 'X') out = c0;
			else if (c1 == 'x') out = tolower(c0);
			else out = c1;
			if (l % 60 == 0) putchar('\n');
			putchar(out);
		}
		putchar('\n');
	}
	for (i = 0; i < 2; ++i) { kseq_destroy(seq[i]); gzclose(fp[i]); }
	return 0;
}

/* ---------------------------------------------------------------------- */
/* dropse / rename                                                         */
/* ---------------------------------------------------------------------- */

static int name_is_diff(const kstring_t *p, const kstring_t *q)
{
	if (p->l != q->l) return 1;
	if (p->l > 2 && p->s[p->l-2] == '/' && q->s[q->l-2] == '/'
		&& isdigit((unsigned char)p->s[p->l-1]) && isdigit((unsigned char)q->s[q->l-1]))
		return strncmp(p->s, q->s, p->l - 2) != 0;
	return strcmp(p->s, q->s) != 0;
}

static int stk_dropse(int argc, char *argv[])
{
	gzFile fp;
	kseq_t *seq, last;
	if (argc == 1 && isatty(fileno(stdin))) {
		fprintf(stderr, "Usage: seqtk dropse <in.fq>\n");
		return 1;
	}
	fp = argc > 1 && strcmp(argv[1], "-")? gzopen(argv[1], "r") : gzdopen(fileno(stdin), "r");
	if (fp == 0) {
		fail_open("stk_dropse");
		return 1;
	}
	seq = kseq_init(fp);
	memset(&last, 0, sizeof(kseq_t));
	while (kseq_read(seq) >= 0) {
		if (last.name.l) {
			if (!name_is_diff(&last.name, &seq->name)) {
				print_seq(stdout, &last, 0);
				print_seq(stdout, seq, 0);
				last.name.l = 0;
			} else cpy_kseq(&last, seq);
		} else cpy_kseq(&last, seq);
	}
	kseq_destroy(seq);
	gzclose(fp);
	free(last.name.s); free(last.seq.s); free(last.qual.s); free(last.comment.s);
	return 0;
}

static int stk_rename(int argc, char *argv[])
{
	gzFile fp;
	kseq_t *seq, last;
	char *prefix = 0;
	uint64_t n = 0;
	if (argc == 1 && isatty(fileno(stdin))) {
		fprintf(stderr, "Usage: seqtk rename <in.fq> [prefix]\n");
		return 1;
	}
	fp = argc > 1 && strcmp(argv[1], "-")? gzopen(argv[1], "r") : gzdopen(fileno(stdin), "r");
	if (fp == 0) {
		fail_open("stk_rename");
		return 1;
	}
	if (argc > 2) prefix = argv[2];
	seq = kseq_init(fp);
	memset(&last, 0, sizeof(kseq_t));
	while (kseq_read(seq) >= 0) {
		char buf[64];
		int same = 0;
		if (last.name.l) {
			if (!name_is_diff(&last.name, &seq->name)) same = 1;
		}
		if (!same) ++n;
		cpy_kseq(&last, seq);
		sprintf(buf, "%" PRIu64, n);
		if (prefix) {
			char *nm = (char*)malloc(strlen(prefix) + strlen(buf) + 1);
			strcpy(nm, prefix); strcat(nm, buf);
			print_seq_named(stdout, &last, 0, nm, 0);
			free(nm);
		} else print_seq_named(stdout, &last, 0, buf, 0);
		if (same) last.name.l = 0;
	}
	kseq_destroy(seq);
	gzclose(fp);
	free(last.name.s); free(last.seq.s); free(last.qual.s); free(last.comment.s);
	return 0;
}

