static int stk_randbase(int argc, char *argv[])
{
	gzFile fp;
	kseq_t *seq;
	int l;
	if (argc == 1) {
		fprintf(stderr, "Usage: seqtk randbase <in.fa>\n");
		return 1;
	}
	fp = open_in(argv[1]);
	if (fp == 0) {
		fail_open("stk_randbase");
		return 1;
	}
	seq = kseq_init(fp);
	while ((l = kseq_read(seq)) >= 0) {
		int i;
		printf(">%s", seq->name.s);
		for (i = 0; i < l; ++i) {
			int c = (unsigned char)seq->seq.s[i];
			int b = nt16_table[c];
			if (bitcnt_table[b] == 2) {
				int lo = b & -b, hi = b ^ lo;
				int p = drand48() < 0.5? hi : lo;
				int ch = nt16_rev_table[p];
				c = islower(c)? tolower(ch) : ch;
			}
			if (i % 60 == 0) putchar('\n');
			putchar(c);
		}
		putchar('\n');
	}
	kseq_destroy(seq);
	gzclose(fp);
	return 0;
}

/* ---------------------------------------------------------------------- */
/* cutN                                                                    */
/* ---------------------------------------------------------------------- */

static void cutN_print_seg(const kseq_t *s, int64_t beg, int64_t end)
{
	printf("%c%s:%" PRId64 "-%" PRId64, s->qual.l? '@' : '>', s->name.s, beg + 1, end);
	print_str(stdout, s->seq.s + beg, end - beg, 60);
	if (s->qual.l) {
		puts("+");
		print_str(stdout, s->qual.s + beg, end - beg, 60);
	}
}

static int stk_cutN(int argc, char *argv[])
{
	int c, l, gap_size = 10, min_size = 1000, gap_only = 0;
	gzFile fp;
	kseq_t *ks;
	while ((c = getopt(argc, argv, "n:p:g")) >= 0) {
		switch (c) {
		case 'n': min_size = atoi(optarg); break;
		case 'p': gap_size = atoi(optarg); break;
		case 'g': gap_only = 1; break;
		default: return 1;
		}
	}
	if (argc == optind) {
		fprintf(stderr, "\n");
		fprintf(stderr, "Usage:   seqtk cutN [options] <in.fa>\n\n");
		fprintf(stderr, "Options: -n INT    min size of N tract [%d]\n", min_size);
		fprintf(stderr, "         -p INT    penalty for a non-N [%d]\n", gap_size);
		fprintf(stderr, "         -g        print gaps only, no sequence\n");
		fprintf(stderr, "\n");
		return 1;
	}
	fp = open_in(argv[optind]);
	if (fp == 0) {
		fail_open("stk_cutN");
		return 1;
	}
	ks = kseq_init(fp);
	while ((l = kseq_read(ks)) >= 0) {
		int64_t i, beg = 0, last = 0, max_i = -1;
		int64_t score = 0, max = 0;
		i = 0;
		while (i <= l) {
			int is_n = i < l && nt16_table[(unsigned char)ks->seq.s[i]] == 15;
			if (is_n) {
				if (score == 0) beg = i;
				++score;
				if (score > max) max = score, max_i = i;
				++i;
				continue;
			}
			if (i < l) score -= gap_size;
			if (score <= 0 || i == l) {
				if (max > 0) {
					int64_t ge = max_i + 1;
					if (ge - beg >= min_size) {
						if (gap_only) {
							if (beg > 0) printf("%s\t%" PRId64 "\t%" PRId64 "\n", ks->name.s, beg, ge);
						} else {
							if (beg > last) cutN_print_seg(ks, last, beg);
							last = ge;
						}
					}
					i = ge;
					max = 0; max_i = -1;
					if (score < 0) score = 0;
					continue;
				}
				if (score < 0) score = 0;
				if (i == l) break;
			}
			++i;
		}
		if (!gap_only && l > last) cutN_print_seg(ks, last, l);
	}
	kseq_destroy(ks);
	gzclose(fp);
	return 0;
}

/* ---------------------------------------------------------------------- */
/* gap                                                                     */
/* ---------------------------------------------------------------------- */

static int stk_gap(int argc, char *argv[])
{
	gzFile fp;
	kseq_t *seq;
	int len, c, min_size = 50;
	while ((c = getopt(argc, argv, "l:")) >= 0) {
		if (c == 'l') min_size = atoi(optarg);
	}
	if (argc == 1) {
		fprintf(stderr, "Usage: seqtk gap [-l %d] <in.fa>\n", min_size);
		return 1;
	}
	if (argv[optind] == 0) crash_segv();
	fp = open_in(argv[optind]);
	if (fp == 0) {
		fail_open("stk_gap");
		return 1;
	}
	seq = kseq_init(fp);
	while ((len = kseq_read(seq)) >= 0) {
		int i, l;
		for (i = l = 0; i <= len; ++i) {
			c = i < len? nt16to4_table[nt16_table[(unsigned char)seq->seq.s[i]]] : 0;
			if (i == len || c < 4) {
				if (l > 0 && l >= min_size)
					printf("%s\t%d\t%d\n", seq->name.s, i - l, i);
				l = 0;
			} else ++l;
		}
	}
	kseq_destroy(seq);
	gzclose(fp);
	return 0;
}

