new = r'''/* ---------------------------------------------------------------------- */
/* subseq                                                                  */
/* ---------------------------------------------------------------------- */

static int all_digits(const char *s)
{
	if (*s == 0) return 0;
	for (; *s; ++s) if (!isdigit((unsigned char)*s)) return 0;
	return 1;
}

/* strict, TAB-separated reader used by the strand-aware mode */
static reghash_t *reg_read_strict(const char *fn)
{
	reghash_t *h;
	gzFile fp;
	kstream_t *ks;
	int dret;
	kstring_t str = {0,0,0};
	fp = open_in(fn);
	if (fp == 0) return 0;
	h = reg_init();
	ks = ks_init(fp);
	while (ks_getuntil(ks, KS_SEP_TAB, &str, &dret) >= 0) {
		int64_t beg = -1, end = -1;
		char strand = '+';
		reglist_t *p = reg_put(h, str.s);
		if (dret != '\n') {
			if (ks_getuntil(ks, KS_SEP_TAB, &str, &dret) > 0 && all_digits(str.s)) beg = atol(str.s);
			if (dret != '\n') {
				if (ks_getuntil(ks, KS_SEP_TAB, &str, &dret) > 0 && all_digits(str.s)) {
					end = atol(str.s);
					if (end < 0) end = -1;
				}
				if (dret != '\n') {
					ks_getuntil(ks, KS_SEP_TAB, &str, &dret);
					if (dret != '\n') {
						ks_getuntil(ks, KS_SEP_TAB, &str, &dret);
						if (dret != '\n') {
							if (ks_getuntil(ks, KS_SEP_TAB, &str, &dret) > 0 && str.s[0] == '-') strand = '-';
						}
					}
				}
			}
		}
		if (dret != '\n') while ((dret = ks_getc(ks)) > 0 && dret != '\n');
		if (end < 0 && beg > 0) end = beg, beg = beg - 1;
		if (beg < 0) beg = 0, end = INT64_MAX;
		if (p->n == p->m) {
			p->m = p->m? p->m<<1 : 4;
			p->a = (region_t*)realloc(p->a, p->m * sizeof(region_t));
		}
		p->a[p->n].beg = beg; p->a[p->n].end = end; p->a[p->n].strand = strand;
		++p->n;
	}
	ks_destroy(ks);
	gzclose(fp);
	free(str.s);
	return h;
}

static void subseq_header(const kseq_t *seq, int64_t beg, int64_t end, int whole)
{
	if (whole) {
		if (seq->comment.l) printf("%c%s %s", seq->qual.l? '@' : '>', seq->name.s, seq->comment.s);
		else printf("%c%s", seq->qual.l? '@' : '>', seq->name.s);
	} else {
		if (seq->comment.l) printf("%c%s:%" PRId64 "-%" PRId64 " %s", seq->qual.l? '@' : '>', seq->name.s, beg+1, end, seq->comment.s);
		else printf("%c%s:%" PRId64 "-%" PRId64, seq->qual.l? '@' : '>', seq->name.s, beg+1, end);
	}
}

static int stk_subseq(int argc, char *argv[])
{
	reghash_t *h;
	gzFile fp;
	kseq_t *seq;
	int l, i, c, is_tab = 0, line = 0, is_strand = 0;
	int64_t j;
	while ((c = getopt(argc, argv, "tl:s")) >= 0) {
		switch (c) {
		case 't': is_tab = 1; break;
		case 's': is_strand = 1; break;
		case 'l': line = atoi(optarg); break;
		}
	}
	if (optind + 2 > argc) {
		fprintf(stderr, "Usage:   seqtk subseq [options] <in.fa> <in.bed>|<name.list>\n");
		fprintf(stderr, "Options:\n");
		fprintf(stderr, "  -t       TAB delimited output\n");
		fprintf(stderr, "  -s       strand aware\n");
		fprintf(stderr, "  -l INT   sequence line length [%d]\n", line);
		fprintf(stderr, "Note: Use 'samtools faidx' if only a few regions are intended.\n");
		return 1;
	}
	h = is_strand? reg_read_strict(argv[optind+1]) : reg_read(argv[optind+1]);
	if (h == 0) {
		fprintf(stderr, "[E::stk_subseq] failed to read the list of regions in file '%s'\n", argv[optind+1]);
		return 1;
	}
	fp = open_in(argv[optind]);
	if (fp == 0) {
		fail_open("stk_subseq");
		return 1;
	}
	seq = kseq_init(fp);
	while ((l = kseq_read(seq)) >= 0) {
		reglist_t *p = reg_get(h, seq->name.s);
		if (p == 0) continue;
		for (i = 0; i < p->n; ++i) {
			int64_t beg = p->a[i].beg, end0 = p->a[i].end, end;
			int whole = (beg == 0 && end0 == INT64_MAX);
			if (beg >= (int64_t)seq->seq.l) {
				fprintf(stderr, "[subseq] %s: %" PRId64 " >= %ld\n", seq->name.s, beg, (long)seq->seq.l);
				continue;
			}
			end = (uint64_t)end0 > seq->seq.l? (int64_t)seq->seq.l : end0;
			if (is_strand) {
				if (end < beg) crash_segv();
				if (is_tab) printf("%s\t%" PRId64 "\t", seq->name.s, beg + 1);
				else subseq_header(seq, beg, end, whole);
				putchar('\n');
				if (p->a[i].strand == '-') {
					for (j = end - 1; j >= beg; --j) putchar(comp_table[(unsigned char)seq->seq.s[j]]);
				} else {
					for (j = beg; j < end; ++j) putchar(seq->seq.s[j]);
				}
				putchar('\n');
				continue;
			}
			if (is_tab) printf("%s\t%" PRId64 "\t", seq->name.s, beg + 1);
			else subseq_header(seq, beg, end, whole);
			for (j = 0; j < end - beg; ++j) {
				if (!is_tab && (j == 0 || (line > 0 && j % line == 0))) putchar('\n');
				putchar(seq->seq.s[beg + j]);
			}
			putchar('\n');
			if (!is_tab && seq->qual.l) {
				putchar('+');
				for (j = 0; j < end - beg; ++j) {
					if (j == 0 || (line > 0 && j % line == 0)) putchar('\n');
					putchar(seq->qual.s[beg + j]);
				}
				putchar('\n');
			}
		}
	}
	kseq_destroy(seq);
	gzclose(fp);
	reg_destroy(h);
	return 0;
}

